const opsCSS = ".ops{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:14px 0}.ops .card{min-width:0}.ops input,.inventory-form input{padding:9px;border:1px solid var(--line);border-radius:8px;max-width:100%;background:var(--surface,#fff);color:var(--ink)}.ops form,.inventory-form{display:flex;flex-wrap:wrap;gap:8px;align-items:end;margin:10px 0}.ops label,.inventory-form label{display:flex;flex-direction:column;gap:4px;font-size:12px}.customer-history{padding:10px;border-bottom:1px solid var(--line)}.customer-history summary{cursor:pointer;font-weight:700}@media(max-width:700px){.ops{grid-template-columns:1fr}.ops form,.inventory-form{flex-direction:column;align-items:stretch}}";
const extendedOpsCSS = "\n.ops-extra{margin:14px 0}.ops-extra h2{font-size:16px;margin:0 0 8px}\n.ops-extra .ops-note{color:var(--muted);font-size:12px;line-height:1.6}\n.ops-extra .ops-warning{color:var(--ink);background:var(--soft);border-left:3px solid var(--royal);border-radius:8px;padding:12px}\n.ops-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:14px 0}\n.ops-grid .card{min-width:0}\n.ops-fields{display:flex;flex-wrap:wrap;gap:10px;align-items:end;margin:14px 0}\n.ops-fields label{display:flex;flex:1;min-width:125px;flex-direction:column;gap:5px;font-size:12px;font-weight:650}\n.ops-fields input,.ops-fields select,.ops-fields textarea{font:inherit;font-size:13px;color:var(--ink);background:var(--surface,#fff);border:1px solid var(--line);border-radius:9px;padding:10px;min-width:0;max-width:100%;width:100%}\n.ops-fields textarea{min-height:80px}\n.ops-fields .ops-check{flex:0;min-width:110px;flex-direction:row;align-items:center}\n.ops-fields .ops-check input{width:auto}\n.ops-fields button{min-height:38px}\n.ops-record{border-bottom:1px solid var(--line);padding:12px 0}\n.ops-record:last-child{border-bottom:0}\n.ops-record strong{display:block;overflow-wrap:anywhere}\n.ops-record p{margin:3px 0 7px;overflow-wrap:anywhere}\n.ops-record .btn{font-size:11px;padding:7px 11px}\n.ops-inline-form{display:flex;gap:7px;flex-wrap:wrap;margin-top:8px}\n.ops-inline-form select,.ops-inline-form input{border:1px solid var(--line);border-radius:7px;padding:8px;background:var(--surface,#fff);color:var(--ink);max-width:220px}\n.ops-low-stock{color:#b91c1c;font-weight:750}\n.ops-range{display:flex;gap:6px;flex-wrap:wrap;margin:9px 0}\n.ops-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;margin:15px 0}\n.ops-kpi{background:var(--surface,#fff);padding:13px;border:1px solid var(--line);border-radius:12px}\n.ops-kpi small{display:block;color:var(--muted);font-size:11px}\n.ops-kpi strong{display:block;margin-top:6px;font-size:clamp(16px,2.2vw,24px);word-break:break-word}\n.ops-chart{display:flex;align-items:stretch;gap:5px;overflow-x:auto;height:160px;padding:10px 0}\n.ops-bar-column{display:flex;flex-direction:column;justify-content:end;align-items:center;flex:1;min-width:25px;max-width:55px;gap:4px}\n.ops-bar{width:100%;background:var(--royal);border-radius:5px 5px 1px 1px;min-height:3px}\n.ops-bar-column small{font-size:8px;white-space:nowrap;color:var(--muted)}\n.ops-extra .btn.primary{background:var(--royal);color:var(--contrast,#fff)}\n@media(max-width:850px){.ops-grid{grid-template-columns:1fr}.ops-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}\n@media(max-width:540px){.ops-fields{flex-direction:column;align-items:stretch}.ops-fields label{width:100%;flex:none}.ops-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}\n";
const applePickerCSS = "\n.apple-date-field{display:flex!important;flex-direction:column;gap:7px;min-width:150px;flex:1 1 170px;font-size:12px;font-weight:700;color:var(--muted);position:relative;overflow:visible}\n.ops>.card:first-child{position:relative;z-index:3;overflow:visible}\n.apple-date-button{display:flex;align-items:center;gap:9px;width:100%;height:46px;padding:0 12px;border:1px solid var(--line);border-radius:13px;background:var(--surface,#fff);color:var(--ink);font-size:13px;font-weight:750;text-align:left;cursor:pointer;transition:border-color .15s,box-shadow .15s}\n.apple-date-button>span{flex:1;white-space:nowrap}\n.apple-date-button .sa-icon{width:18px;height:18px;color:var(--royal);flex-shrink:0}\n.apple-date-button .cal-chevron{width:13px;height:13px;transform:rotate(90deg);color:var(--muted)}\n.apple-date-button[aria-expanded=true],.apple-date-button:hover{border-color:var(--royal);box-shadow:0 0 0 3px var(--soft)}\n.apple-date-button:focus-visible,.apple-picker button:focus-visible{outline:2px solid var(--royal);outline-offset:2px}\n.apple-picker[hidden]{display:none!important}\n.apple-picker{position:absolute;z-index:60;box-sizing:border-box;width:280px;max-width:calc(100% - 20px);padding:12px 11px 10px;border:1px solid var(--line);border-radius:16px;background:var(--surface,#fff);color:var(--ink);box-shadow:0 14px 36px #0003,0 2px 9px #0001;font-family:-apple-system,BlinkMacSystemFont,\"SF Pro Text\",Inter,system-ui,sans-serif}\n.apple-picker-header{display:flex;align-items:center;justify-content:space-between;gap:9px;margin-bottom:8px}\n.apple-picker-month{font-size:15px;font-weight:800;letter-spacing:-.35px}\n.apple-picker-month-buttons{display:flex;gap:8px}\n.apple-picker button{cursor:pointer;font-family:inherit}\n.apple-picker-arrow{display:flex;align-items:center;justify-content:center;width:29px;height:29px;border:0;border-radius:9px;color:var(--royal);background:var(--soft)}\n.apple-picker-arrow:hover{filter:brightness(.96)}\n.apple-picker-arrow .sa-icon{width:17px;height:17px}\n.apple-picker-arrow.previous .sa-icon{transform:rotate(180deg)}\n.apple-picker-weekdays,.apple-picker-days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:3px;text-align:center}\n.apple-picker-weekdays{color:var(--muted);font-size:11px;font-weight:800;margin-bottom:7px}\n.apple-picker-weekdays span{height:22px;display:flex;align-items:center;justify-content:center}\n.apple-picker-days button{border:0;border-radius:50%;background:transparent;color:var(--ink);width:100%;aspect-ratio:1;min-height:32px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:650}\n.apple-picker-days button:hover{background:var(--hover)}\n.apple-picker-days button.outside{opacity:.34}\n.apple-picker-days button.between:not(.selected){background:var(--soft);color:var(--softText);border-radius:10px}\n.apple-picker-days button.today:not(.selected){box-shadow:inset 0 0 0 1.5px var(--royal)}\n.apple-picker-days button.selected,.apple-picker-days button.selected:hover{background:var(--royal);color:var(--contrast,#fff);font-weight:850;box-shadow:0 4px 10px #0002}\n.apple-picker-footer{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--line);margin-top:8px;padding-top:6px}\n.apple-picker-footer button{background:transparent;border:0;color:var(--royal);font-size:11px;font-weight:800;border-radius:9px;padding:6px 8px}\n.apple-picker-footer button:hover{background:var(--soft)}\n.apple-picker-footer span{font-size:11px;color:var(--muted)}\n@media(max-width:700px){.apple-date-field{width:100%;flex:none}.apple-date-button{height:46px}.apple-picker{border-radius:16px;padding:12px 11px 9px}.apple-picker-days button{min-height:32px}}\n";
