const mobileNavCSS = "\n.side-head,.side-links{display:contents}\n.menu-toggle{display:none}\n@media(max-width:720px){\n .shell{overflow:visible}\n .side{display:flex;flex-direction:column;align-items:stretch;gap:0;position:relative;overflow:visible;z-index:30;padding:0}\n .side-head{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;padding:4px 2px 11px}\n .side-head .brand{font-size:16px;margin:0;min-width:0}\n .menu-toggle{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid var(--line);border-radius:11px;min-height:43px;padding:9px 12px;background:var(--surface,#fff);color:var(--ink);font-weight:800;font-size:12px;cursor:pointer;flex-shrink:0}\n .menu-toggle .sa-icon{width:20px;height:20px;color:var(--royal)}\n .side-links{display:none;flex-direction:column;gap:3px;position:absolute;top:100%;left:0;right:0;padding:12px;background:var(--surface,#fff);border:1px solid var(--line);border-radius:14px;box-shadow:0 16px 36px #0003;max-height:min(73vh,560px);overflow-y:auto;overscroll-behavior:contain;z-index:40}\n .side.is-open .side-links{display:flex}\n .side-links .nav-label{display:block;margin:0 10px 8px;font-size:11px}\n .side-links .nav{width:100%;white-space:normal;padding:12px 13px;min-height:44px;font-size:14px}\n .side-links .nav-content{gap:12px}\n .side-links .nav .sa-icon{width:18px;height:18px}\n .side.is-open .menu-toggle{border-color:var(--blue);box-shadow:0 0 0 2px var(--soft,#e1e8fb)}\n}\n";
